function escapeHtml(value){const element=document.createElement("div");element.textContent=String(value??"");return element.innerHTML;}
function normalizePath(pathname){const path=String(pathname||"").replace(/\/+$/,"");return path.startsWith("/portal")?path||"/portal":"/portal";}
function pathParts(pathname=location.pathname){return normalizePath(pathname).split("/").filter(Boolean).slice(1);}
function setConnection(state,text){connection.dataset.state=state;connection.querySelector("span").textContent=text;}
function setAccessIndicator(){setConnection(accessAllowed?"access-granted":"access-denied",accessAllowed?"已開通":"未開通");}
function applyElectronicAvailability(enabled){allElectronicGamesEnabled=Boolean(enabled);categories.atg.items.forEach(item=>{item.disabled=item.id!=="set2"&&!allElectronicGamesEnabled;item.disabledLabel=item.disabled?"暫停開放":"";});}
function applyRuntimeAccess(value,{rerender=false}={}){const previousAccess=accessAllowed;const previousElectronic=allElectronicGamesEnabled;const previousAdmin=isAdmin;accessAllowed=Boolean(value.accessAllowed);isAdmin=Boolean(value.isAdmin);adminMonitorButton.hidden=!isAdmin;applyElectronicAvailability(value.allElectronicGamesEnabled!==false);setAccessIndicator();if(rerender&&(previousAccess!==accessAllowed||previousElectronic!==allElectronicGamesEnabled||previousAdmin!==isAdmin)){routeRevision+=1;activeOperation=null;renderRoute();}}
function toast(title,detail){const item=document.createElement("div");item.className="toast";item.innerHTML=`<b>${escapeHtml(title)}</b><span>${escapeHtml(detail)}</span>`;toasts.append(item);setTimeout(()=>item.remove(),4000);}
function isStandaloneApp(){return matchMedia("(display-mode: standalone)").matches||navigator.standalone===true;}
function isIosDevice(){return /iphone|ipad|ipod/i.test(navigator.userAgent)||(navigator.platform==="MacIntel"&&navigator.maxTouchPoints>1);}
function setInstallVisibility(){installButton.hidden=isStandaloneApp()||(!deferredInstallPrompt&&!isIosDevice());}
function closeInstallDialog(){installDialog.hidden=true;}
function showInstallHelp(){const ios=isIosDevice();installInstructions.innerHTML=ios?`<ol><li>點擊 Safari 下方的「分享」圖示</li><li>選擇「加入主畫面」</li><li>確認名稱後點擊「新增」</li></ol><p>安裝後請從桌面的黑域AI圖示開啟。</p>`:`<ol><li>開啟瀏覽器選單</li><li>選擇「安裝應用程式」或「加到主畫面」</li><li>完成後從桌面開啟黑域AI</li></ol>`;installDialog.hidden=false;}
async function installPwa(){if(!deferredInstallPrompt){showInstallHelp();return;}const prompt=deferredInstallPrompt;deferredInstallPrompt=null;await prompt.prompt();const choice=await prompt.userChoice;if(choice.outcome==="accepted")toast("正在安裝黑域AI","完成後可從桌面直接開啟");setInstallVisibility();}
function renderOffline(){setConnection("offline","網路中斷");view.innerHTML=`<section class="screen offline-screen"><article><img src="/portal/icons/icon-192.png" alt="黑域AI"><p>BLACKDOMAIN AI</p><h1>目前沒有網路連線</h1><span>為避免顯示舊房況與舊分析，離線時不提供分析資料。</span><button type="button" onclick="location.reload()">重新連線</button></article></section>`;}
function navigate(path,{replace=false}={}){if(adminMonitorTimer){clearInterval(adminMonitorTimer);adminMonitorTimer=null;}const normalized=normalizePath(path);if(replace)history.replaceState({},"",normalized);else history.pushState({},"",normalized);currentPath=normalized;activeOperation=null;routeRevision+=1;renderRoute();}
let homeStopInFlight=false;
async function stopMonitoringAndGoHome(){if(homeStopInFlight)return;homeStopInFlight=true;loading.hidden=false;try{const response=await fetch("/api/web/stop",{method:"POST",headers:{"content-type":"application/json","x-blackdomain-portal":"1"},body:"{}"});if(response.status===401){authenticated=false;renderLogin();return;}if(!response.ok)throw new Error(`HTTP ${response.status}`);resumeBaccaratSession=false;restoredMessages=[];navigate("/portal/");}catch(error){console.error("Portal monitoring stop failed",error);toast("尚未停止監控","連線異常，請再按一次首頁。");}finally{loading.hidden=true;homeStopInFlight=false;}}
function backTo(path){navigate(path);}
function pageHeader(title,subtitle,backPath){return `<div class="page-heading">${backPath?`<button class="back-button" data-go="${backPath}">← 返回</button>`:"<p class=\"eyebrow\">BLACKDOMAIN AI</p>"}<h1>${escapeHtml(title)}</h1><p>${escapeHtml(subtitle)}</p></div>`;}
function homeGameList(item){if(!Array.isArray(item.items))return "";return `<div class="home-game-list" aria-label="包含遊戲">${item.items.map(game=>`<small${game.disabled?' class="is-maintenance"':""}>${escapeHtml(game.fullName||game.name)}${game.disabled?"・維護中":""}</small>`).join("")}</div>`;}
function card(item,path,{home=false}={}){const disabledLabel=item.disabledLabel||(item.id==="horse"?"維護中":"暫停開放");return `<button class="selection-card${item.disabled?" is-disabled":""}${home?" home-category-card":""}" ${item.disabled?'disabled aria-disabled="true"':`data-go="${path}"`}><div class="image-frame"><img src="${item.image}" alt="${escapeHtml(item.name)}" loading="${home?"eager":"lazy"}" onerror="this.closest('.image-frame').classList.add('image-error');this.remove()">${item.disabled?`<b class="maintenance-badge">${escapeHtml(disabledLabel)}</b>`:""}</div><div class="selection-copy"><div><h2>${escapeHtml(item.name)}</h2><p>${escapeHtml(item.disabled?disabledLabel:item.subtitle)}</p>${home?homeGameList(item):""}</div><span>${item.disabled?disabledLabel:"進入分析"}</span></div></button>`;}
function renderHome(){view.innerHTML=`<section class="screen home-screen"><div class="home-intro"><p class="eyebrow">BLACKDOMAIN AI</p><h1>黑域AI智能分析系統</h1><p>請選擇分析項目</p></div><div class="category-grid">${categoryOrder.map(key=>card(categories[key],`/portal/${key}`,{home:true})).join("")}</div></section>`;}
function renderCategory(categoryKey){const category=categories[categoryKey];if(!category)return navigate("/portal/",{replace:true});view.innerHTML=`<section class="screen">${pageHeader(`${category.name} AI`,`選擇要進入的項目`,"/portal/")}<div class="selection-grid">${category.items.map(item=>card(item,`/portal/${categoryKey}/${item.id}`)).join("")}</div></section>`;}
function actionButton(label,path,primary=true,description=""){return `<button class="action-card${primary?" primary":""}" data-go="${escapeHtml(path)}"><span><b>${escapeHtml(label)}</b>${description?`<small>${escapeHtml(description)}</small>`:""}</span><i>進入</i></button>`;}
async function initializeGame(categoryKey,item){if(categoryKey==="baccarat"){await send("百家樂",{showBusy:false,silent:true});return send(item.command,{showBusy:true,silent:false});}if(categoryKey==="atg")return send(item.command,{showBusy:false,silent:true});return null;}
function itemFor(categoryKey,itemId){return categories[categoryKey]?.items.find(entry=>entry.id===itemId)||null;}
function renderGame(categoryKey,itemId){const item=itemFor(categoryKey,itemId);if(!item||item.disabled)return navigate(`/portal/${categoryKey}`,{replace:true});activeOperation={categoryKey,item,mode:"menu"};let actions="";if(categoryKey==="atg")actions=actionButton("AI推薦房",`/portal/${categoryKey}/${itemId}/recommend`,true,"由 AI 分析目前房間數據");else if(categoryKey==="baccarat")actions=actionButton("進入百家樂分析",`/portal/${categoryKey}/${itemId}/analyze`,true,"依步驟設定房間、本金與配注模式");else actions=actionButton(`開始${item.name}分析`,`/portal/${categoryKey}/${itemId}/analyze`,true,"取得目前最新分析資料");view.innerHTML=`<section class="screen operation-screen">${pageHeader(item.fullName||item.name,item.subtitle,`/portal/${categoryKey}`)}<article class="game-identity"><div class="game-image"><img src="${item.image}" alt="${escapeHtml(item.name)}" onerror="this.closest('.game-image').classList.add('image-error');this.remove()"></div><div><p>目前選擇</p><h2>${escapeHtml(item.fullName||item.name)}</h2><span>${escapeHtml(item.subtitle)}</span></div></article><div class="operation-panel"><h2>開始分析</h2><p>AI 將依照最新房況資料推薦合適房間</p><div class="operation-actions">${actions}</div></div></section>`;if(categoryKey==="atg")initializeGame(categoryKey,item);}
function analysisCopy(mode){if(mode==="recommend")return ["AI推薦房","正在同步平台資料並分析房間數據"];return ["AI分析","依照畫面步驟完成設定並取得結果"];}
function analysisFlowSteps(categoryKey,item){if(categoryKey==="baccarat")return["選擇房號","本金與配注","自動分析"];if(categoryKey==="atg")return["同步房況","篩選房間","推薦結果"];if(categoryKey==="lottery"&&item?.id==="539")return["同步開獎","AI運算","推薦號碼"];if(categoryKey==="sports")return["同步賽事","AI分析","分析結果"];return["同步資料","AI分析","分析結果"];}
function analysisStepHeader(labels,active,id="analysisStepper"){return `<div class="mb-stepper analysis-flow"${id?` id="${id}"`:""} aria-label="分析步驟">${labels.map((label,index)=>`<div class="${index+1===active?"active":index+1<active?"done":""}"><i>${index+1<active?"✓":index+1}</i><span>${label}</span></div>`).join("")}</div>`;}
function setAnalysisFlowStep(active){document.querySelectorAll("#analysisStepper>div").forEach((step,index)=>{step.classList.toggle("active",index+1===active);step.classList.toggle("done",index+1<active);step.querySelector("i").textContent=index+1<active?"✓":String(index+1);});}
function mbStepHeader(active){return analysisStepHeader(["選擇賽道","選擇碼數","開始分析"],active,"");}
function renderMbShell(content,backPath="/portal/lottery/mb"){view.innerHTML=`<section class="screen analysis-screen mb-analysis-screen">${pageHeader("MB彈珠分析","依序完成設定後開始分析",backPath)}${content}</section>`;requestAnimationFrame(()=>scrollTo({top:0,behavior:"instant"}));}
function renderMbTrackPicker(){mbSelection={track:null,count:null};renderMbShell(`${mbStepHeader(1)}<div class="mb-section-heading"><div><p>STEP 01</p><h2>選擇賽道</h2></div><span>4 個即時賽道</span></div><div class="mb-track-grid">${mbTracks.map(track=>`<button class="mb-track-card" data-mb-track="${track.id}"><span class="mb-track-image"><img src="${track.image}" alt="${track.name}" loading="eager"></span><span class="mb-track-copy"><b>${track.name}</b><small>選擇此賽道</small><i>進入</i></span></button>`).join("")}</div>`);}
function renderMbCountPicker(trackId){const track=mbTracks.find(entry=>entry.id===trackId);if(!track)return renderMbTrackPicker();mbSelection={track,count:null};renderMbShell(`${mbStepHeader(2)}<article class="mb-selected-track"><img src="${track.image}" alt="${track.name}"><div><p>目前賽道</p><h2>${track.name}</h2><button data-mb-back="tracks">重新選擇賽道</button></div></article><div class="mb-section-heading"><div><p>STEP 02</p><h2>選擇推薦碼數</h2></div><span>3 至 6 碼</span></div><div class="mb-count-grid">${mbCounts.map(count=>`<button data-mb-count="${count}"><strong>${count}<small>碼</small></strong><span>冠、亞、季軍各推薦 ${count} 碼</span><i>選擇</i></button>`).join("")}</div>`);}
function renderMbConfirmation(count){const track=mbSelection.track;if(!track||!mbCounts.includes(Number(count)))return renderMbTrackPicker();mbSelection.count=Number(count);renderMbShell(`${mbStepHeader(3)}<div class="mb-section-heading"><div><p>STEP 03</p><h2>確認分析設定</h2></div><span>準備完成</span></div><article class="mb-confirm-card"><img src="${track.image}" alt="${track.name}"><div class="mb-confirm-summary"><div><span>賽道</span><strong>${track.name}</strong></div><div><span>推薦碼數</span><strong>${mbSelection.count} 碼</strong></div></div><button class="mb-start-button" data-mb-start>開始分析</button><button class="mb-secondary-button" data-mb-back="counts">返回選擇碼數</button></article>`);}
function startMbAnalysis(){const {track,count}=mbSelection;if(!track||!count)return renderMbTrackPicker();renderMbShell(`${mbStepHeader(3)}<div id="analysisStage" class="analysis-stage"><div class="analysis-progress"><div class="scan-orbit"><span>MB</span></div><h2>正在分析 ${track.name}</h2><p>正在同步最新賽果並計算冠、亞、季軍推薦號碼。</p><div class="progress-line"><i></i></div></div></div><div id="result"></div>`);send(`MB ${track.name} ${count}碼`,{showBusy:false});}
async function startElectronicRecommendation(item){const revision=routeRevision;await send(item.command,{showBusy:false,silent:true});if(revision!==routeRevision||activeOperation?.categoryKey!=="atg"||activeOperation?.mode!=="recommend")return;await send("AI推薦房",{showBusy:false});}
function restartElectronicRecommendation(){if(activeOperation?.categoryKey!=="atg"||activeOperation?.mode!=="recommend")return false;navigate(currentPath,{replace:true});return true;}
function renderAnalysis(categoryKey,itemId,mode){const item=itemFor(categoryKey,itemId);if(!item||item.disabled)return navigate(`/portal/${categoryKey}`,{replace:true});activeOperation={categoryKey,item,mode,startedAt:Date.now()};if(categoryKey==="lottery"&&item.id==="mb")return renderMbTrackPicker();const [title,subtitle]=analysisCopy(mode);const initialStep=categoryKey==="baccarat"?1:2;view.innerHTML=`<section class="screen analysis-screen">${pageHeader(title,`${item.fullName||item.name}・${subtitle}`,`/portal/${categoryKey}/${itemId}`)}${analysisStepHeader(analysisFlowSteps(categoryKey,item),initialStep)}<div id="analysisStage" class="analysis-stage"><div class="analysis-progress"><div class="scan-orbit"><span>AI</span></div><h2>正在分析</h2><p>平台資料同步完成後將自動顯示結果，請勿重複點擊。</p><div class="progress-line"><i></i></div></div></div><div id="result"></div></section>`;if(categoryKey==="baccarat"&&resumeBaccaratSession&&resumeBaccaratPlatform===item.command){resumeBaccaratSession=false;const latest=[...restoredMessages].reverse().find(entry=>(entry.messages||[]).some(messageBelongsToActiveOperation))?.messages||[];if(latest.length)renderResults(latest,{enforceScope:true});else{setAnalysisFlowStep(3);document.querySelector("#analysisStage h2").textContent="監控已恢復";document.querySelector("#analysisStage p").textContent="下一局開獎後會自動更新分析。";}}else if(categoryKey==="baccarat")initializeGame(categoryKey,item);else if(categoryKey==="atg"&&mode==="recommend")startElectronicRecommendation(item);else send(item.command,{showBusy:false});}
function renderVip(){const item=categories.vip.items[0];activeOperation={categoryKey:"vip",item,mode:"status"};view.innerHTML=`<section class="screen operation-screen vip-center-screen">${pageHeader("VIP會員權限","查看會員資格、有效期限與可使用功能","/portal/")}<div id="result"><section class="result-view"><div class="vip-skeleton"><div></div><div></div><div></div><p>正在讀取會員資料…</p></div></section></div></section>`;send("VIP",{showBusy:false});}
function healthStateLabel(state){return({healthy:"正常",degraded:"部分異常",stale:"資料逾時",offline:"未連線",maintenance:"維護中"})[state]||"未知";}
function adminProviderMarkup(provider){const metrics=provider.metrics||{};const metricItems=Object.entries(metrics).map(([key,value])=>`<div><span>${escapeHtml(({tables:"房桌",roomsWithHistory:"有效牌桌",tracks:"賽道",tracksWithHistory:"有效賽道"})[key]||key)}</span><strong>${escapeHtml(value)}</strong></div>`).join("");const games=Array.isArray(provider.games)?`<div class="admin-game-list">${provider.games.map(game=>`<div><b>${escapeHtml(game.gameName)}</b><span class="health-pill ${game.state}">${healthStateLabel(game.state)}</span><small>${escapeHtml(game.tables)} 房・${escapeHtml(game.emptyRooms)} 空房・${escapeHtml(game.pagesCovered)} 頁</small></div>`).join("")}</div>`:"";return `<article class="admin-provider"><header><div><p>${escapeHtml(provider.id)}</p><h2>${escapeHtml(provider.label)}</h2></div><span class="health-pill ${provider.state}">${healthStateLabel(provider.state)}</span></header>${metricItems?`<div class="admin-metrics">${metricItems}</div>`:""}${games}<footer>最後資料：${provider.lastUpdatedAt?escapeHtml(new Date(provider.lastUpdatedAt).toLocaleString("zh-TW")):"尚未收到"}${Number.isFinite(provider.ageSeconds)?`・${escapeHtml(provider.ageSeconds)} 秒前`:""}</footer></article>`;}
async function refreshAdminMonitor(){if(!isAdmin||normalizePath(location.pathname)!=="/portal/admin/monitor")return;const target=document.querySelector("#adminMonitorContent");if(!target)return;try{const response=await fetch("/api/web/admin/monitor",{cache:"no-store"});if(response.status===403)return navigate("/portal/",{replace:true});if(!response.ok)throw new Error(`HTTP ${response.status}`);const data=await response.json();target.innerHTML=`<div class="admin-overview"><div><span>系統狀態</span><strong class="${data.service.state}">${healthStateLabel(data.service.state)}</strong></div><div><span>網站分析</span><strong>主要服務</strong></div><div><span>LINE分析</span><strong>${data.delivery.lineWebsiteOnlyMode?"暫停・導向網站":"啟用"}</strong></div><div><span>服務運行</span><strong>${Math.floor(data.service.uptimeSeconds/3600)} 小時</strong></div></div><div class="admin-provider-grid">${data.providers.map(adminProviderMarkup).join("")}</div><p class="admin-updated">管理員專用・更新時間 ${escapeHtml(new Date(data.generatedAt).toLocaleString("zh-TW"))}</p>`;}catch(error){target.innerHTML=`<div class="admin-monitor-error"><b>監控資料讀取失敗</b><span>系統會自動重新連線。</span></div>`;}}
function renderAdminMonitor(){if(!isAdmin)return navigate("/portal/",{replace:true});activeOperation={categoryKey:"admin",mode:"monitor"};view.innerHTML=`<section class="screen admin-monitor-screen">${pageHeader("系統監控中心","僅管理員可查看","/portal/")}<div id="adminMonitorContent"><div class="vip-skeleton"><div></div><div></div><p>正在讀取系統狀態…</p></div></div></section>`;refreshAdminMonitor();adminMonitorTimer=setInterval(refreshAdminMonitor,10000);}
function renderAccessDenied(categoryKey){const back=categories[categoryKey]?`/portal/${categoryKey}`:"/portal/";view.innerHTML=`<section class="screen access-screen">${pageHeader("需要開通權限","BLACKDOMAIN AI",back)}<article class="access-card"><div class="access-lock">VIP</div><h2>請聯絡管理員</h2><p>LINE：@893jrweh</p><a href="https://line.me/ti/p/@893jrweh" class="access-contact">聯絡管理員</a></article></section>`;}
function renderRoute(){if(!authenticated)return renderLogin();const [categoryKey,itemId,mode]=pathParts();if(!categoryKey)return renderHome();if(categoryKey==="admin")return renderAdminMonitor();if(categoryKey==="vip")return renderVip();if(!itemId)return renderCategory(categoryKey);if(!accessAllowed)return renderAccessDenied(categoryKey);if(categoryKey==="atg"&&mode==="custom")return navigate(`/portal/${categoryKey}/${itemId}`,{replace:true});if(mode)return renderAnalysis(categoryKey,itemId,mode);renderGame(categoryKey,itemId);requestAnimationFrame(()=>{view.focus({preventScroll:true});scrollTo({top:0,behavior:"instant"});});}
