function sportsResultCarousel(messages){const cards=[];messages.forEach(message=>{const bubbles=message?.contents?.type==="carousel"?message.contents.contents:[message.contents];bubbles.filter(Boolean).forEach(bubble=>{const data=walk(bubble);const texts=data.texts.map(String).map(text=>text.trim()).filter(text=>text&&!/^BLACKDOMAIN/i.test(text));const title=message.altText||texts.shift()||"體育AI分析";cards.push({title,body:genericResultBody(texts)});});});if(cards.length<2)return"";return `<section class="sports-carousel" data-sports-index="0"><div class="sports-game-tabs" role="tablist">${cards.map((card,index)=>`<button role="tab" data-sports-game="${index}" class="${index===0?"active":""}">第 ${index+1} 場</button>`).join("")}</div><div class="sports-slides">${cards.map((card,index)=>`<article class="result-card sports-slide${index===0?" active":""}" data-sports-slide="${index}"><div class="result-head"><div><p>SPORTS AI ANALYSIS</p><h2>${escapeHtml(card.title)}</h2></div><span class="ready">第 ${index+1}/${cards.length} 場</span></div><div class="professional-result">${card.body}</div></article>`).join("")}</div><div class="sports-pager"><button data-sports-move="prev" disabled>上一場</button><span><b>1</b> / ${cards.length}</span><button data-sports-move="next">下一場</button></div></section>`;}
function showSportsGame(index){const carousel=document.querySelector(".sports-carousel");if(!carousel)return;const total=carousel.querySelectorAll("[data-sports-slide]").length;const current=Math.max(0,Math.min(Number(index)||0,total-1));carousel.dataset.sportsIndex=String(current);carousel.querySelectorAll("[data-sports-slide]").forEach((slide,position)=>slide.classList.toggle("active",position===current));carousel.querySelectorAll("[data-sports-game]").forEach((tab,position)=>{tab.classList.toggle("active",position===current);tab.setAttribute("aria-selected",String(position===current));});carousel.querySelector(".sports-pager span b").textContent=String(current+1);carousel.querySelector('[data-sports-move="prev"]').disabled=current===0;carousel.querySelector('[data-sports-move="next"]').disabled=current===total-1;carousel.scrollIntoView({behavior:"smooth",block:"start"});}
function mbResultCard(message,data){const texts=data.texts.map(String).map(text=>text.trim()).filter(Boolean);const alt=String(message.altText||"");const track=mbTracks.find(entry=>alt.includes(entry.name)||texts.some(text=>text.includes(entry.name)))||mbSelection.track;const count=Number(alt.match(/([3-6])碼/)?.[1]||mbSelection.count||0);const unavailable=texts.includes("資料狀態")&&!texts.some(text=>/期 AI推薦$/.test(text));if(unavailable){const state=valueAfter(texts,"資料狀態","同步中");const detail=texts.find(text=>/資料|同步|推薦/.test(text)&&text.length>12)||"即時資料尚未完成同步，暫不使用不完整資料推薦。";return `<article class="result-card mb-result-card"><div class="result-head"><div><p>MB MARBLE ANALYSIS</p><h2>${escapeHtml(track?.name||"MB彈珠")}</h2></div><span class="ready is-waiting">同步中</span></div><section class="mb-data-wait"><b>${escapeHtml(state)}</b><p>${escapeHtml(detail)}</p></section><div class="result-actions"><button class="operation-button primary" data-mb-restart>重新選擇</button></div></article>`;}
const period=valueAfter(texts,"預測期號","等待下一期");const updated=valueAfter(texts,"最後同步","—");const settlement=valueAfter(texts,"自動結算","");const history=mbRecentRecords(texts);const ranks=[{label:"冠軍",className:"champion"},{label:"亞軍",className:"runner-up"},{label:"季軍",className:"third"}].map(rank=>({...rank,picks:mbRankPicks(texts,rank.label,count)}));return `<article class="result-card mb-result-card"><div class="result-head"><div><p>MB MARBLE ANALYSIS</p><h2>${escapeHtml(track?.name||"MB彈珠")} · ${escapeHtml(count||"—")}碼</h2></div><span class="ready">${settlement?"自動更新":"分析完成"}</span></div>${track?`<div class="mb-result-track"><img src="${track.image}" alt="${track.name}"><div><span>分析賽道</span><strong>${track.name}</strong></div></div>`:""}<div class="mb-period"><span>預測期號</span><strong>${escapeHtml(period)}</strong><small>最後同步 ${escapeHtml(updated)}</small></div>${settlement?`<div class="mb-settlement"><i>✓</i><span><b>本場已自動結算</b>${escapeHtml(settlement)}</span></div>`:""}<section class="mb-ranking"><div class="metric-title"><b>AI 定位推薦</b><span>冠、亞、季軍</span></div>${ranks.map(rank=>`<div class="mb-rank-row ${rank.className}"><strong>${rank.label}</strong><span>${mbNumberChips(rank.picks)}</span></div>`).join("")}</section><div class="mb-period-notice"><i>✓</i><span><b>請核對預測期號</b>是否與平台相同</span><em>下一場自動分析</em></div>${mbHistoryMarkup(history)}<p class="mb-disclaimer">依該賽道最新資料進行名次定位分析，僅供娛樂參考。</p><div class="result-actions"><button class="operation-button primary" data-mb-restart>重新選擇賽道與碼數</button></div></article>`;}
function messageBelongsToActiveOperation(message){if(!activeOperation)return false;const data=message.type==="text"?{texts:[message.text]}:walk(message.contents);const content=[message.altText,...(data.texts||[])].filter(Boolean).join(" ");const {categoryKey,item}=activeOperation;if(categoryKey==="baccarat")return /百家樂|牌路|本房牌路統計|\bDG\b|\bMT\b/.test(content);if(categoryKey==="atg")return /AI推薦房|推薦房號|房間數據|電子|戰神|賽特|古神|巴風特|虎小妹|赤三國/.test(content)&&(!/戰神賽特[12]|古神巴風特|虎小妹|赤三國/.test(content)||content.includes(item.fullName||item.name));if(categoryKey==="lottery"){if(item.id==="mb")return /MB|彈珠|號碼/.test(content);if(item.id==="539")return /539|今彩|預測號碼/.test(content);}if(categoryKey==="sports")return new RegExp(`\\b${item.name}\\b|體育|賽事|比分`).test(content);return true;}
function resultCard(message){const data=message.type==="text"?{texts:[message.text],actions:[],images:[]}:walk(message.contents);const rawTexts=data.texts.map(String).map(text=>text.trim()).filter(text=>text&&!/^BLACKDOMAIN/i.test(text));const texts=[...new Set(rawTexts)];const allActions=[...data.actions,...quickReplyActions(message)];const uniqueActions=[...new Map(allActions.filter(action=>action.text||action.uri).map(action=>[action.text||action.uri,action])).values()].filter(action=>!/^返回首頁$/.test(action.text||""));const roomPlatform=/^(DG|MT)\s*房號選擇$/i.exec(String(message.altText||""))?.[1]?.toUpperCase();if(roomPlatform)return baccaratRoomSelectionCard(roomPlatform,uniqueActions);if(/本金|單注上限/.test(String(message.altText||"")))return baccaratInputCard(message,{...data,texts:rawTexts},uniqueActions.slice(0,8));if(/^MB彈珠AI/.test(String(message.altText||"")))return mbResultCard(message,{...data,texts:rawTexts});const actions=uniqueActions.slice(0,8);if(message.altText==="539AI"&&texts.includes("AI預測"))return lottery539ResultCard({...data,texts:rawTexts},actions);if(message.altText==="AI推薦房"||texts.includes("推薦房號"))return recommendationCard({...data,texts},actions);if(message.altText==="百家樂AI 分析結果"||texts.includes("本房牌路統計"))return baccaratResultCard({...data,texts:rawTexts},actions);if(message.altText==="VIP中心"||message.altText==="免費權限"||texts.includes("VIP狀態")||texts.includes("權限狀態"))return vipResultCard({...data,texts:rawTexts},actions);const title=message.altText||texts.shift()||"AI 分析結果";const image=data.images[0]?`<div class="result-image"><img src="${escapeHtml(data.images[0])}" alt=""></div>`:"";return `<article class="result-card">${image}<div class="result-head"><div><p>AI ANALYSIS COMPLETE</p><h2>${escapeHtml(title)}</h2></div><span class="ready">已同步</span></div><div class="professional-result">${genericResultBody(texts)}</div>${actionMarkup(actions)}</article>`;}
function localizeResultLabels(target){const labels={"AI RECOMMENDED ROOM":"AI推薦結果","BACCARAT AI ANALYSIS":"百家樂分析結果","AI ANALYSIS COMPLETE":"分析完成"};target.querySelectorAll(".result-head p").forEach(element=>{element.textContent=labels[element.textContent]||element.textContent;});}
function showAnalysisState(title,detail,{error=false}={}){const stage=document.querySelector("#analysisStage");if(!stage)return;stage.classList.toggle("has-error",error);const heading=stage.querySelector("h2");const copy=stage.querySelector("p");if(heading)heading.textContent=title;if(copy)copy.textContent=detail;}
function renderResults(messages,{enforceScope=false,automatic=false}={}){const target=document.querySelector("#result");if(!target)return false;const incoming=Array.isArray(messages)?messages:[messages];const list=enforceScope?incoming.filter(messageBelongsToActiveOperation):incoming;if(!list.length){if(!automatic)showAnalysisState("尚未取得分析結果","資料回覆格式異常，請返回上一頁後重新進入。",{error:true});return false;}const flowContent=list.map(message=>[message.altText,...walk(message.type==="text"?null:message.contents).texts,message.text].filter(Boolean).join(" ")).join(" ");const flowStep=activeOperation?.categoryKey==="baccarat"?(/房號選擇/.test(flowContent)?1:/本房牌路統計|百家樂AI 分析結果/.test(flowContent)?3:2):3;setAnalysisFlowStep(flowStep);const automaticBaccarat=automatic&&activeOperation?.categoryKey==="baccarat";document.querySelector("#analysisStage")?.remove();const roundNotice=automaticBaccarat?'<div class="round-update" role="status"><i>✓</i><div><b>本局已結算</b><span>下一局分析已自動更新</span></div></div>':"";const sportsCarousel=activeOperation?.categoryKey==="sports"?sportsResultCarousel(list):"";target.innerHTML=`<section class="result-view${automaticBaccarat?" automatic-round-update":""}">${roundNotice}<div class="result-view-heading"><h2>分析結果</h2><p>${automaticBaccarat?"下一局最新分析":"本次最新資料"}</p></div>${sportsCarousel||list.map(resultCard).join("")}</section>`;localizeResultLabels(target);if(activeOperation?.categoryKey==="baccarat"&&list.some(message=>{const data=message.type==="text"?{texts:[message.text]}:walk(message.contents);return (data.texts||[]).includes("本房牌路統計");}))document.querySelector("#baccaratForm")?.remove();if(automaticBaccarat)toast("本局已結算","下一局分析已自動完成");target.scrollIntoView({behavior:"smooth",block:"start"});return true;}
async function send(text,{showBusy=true,silent=false,retryCount=0}={}){if(!text)return false;const revision=routeRevision;if(showBusy)loading.hidden=false;const controller=new AbortController();const requestTimeout=setTimeout(()=>controller.abort(),25_000);try{const response=await fetch("/api/web/command",{method:"POST",headers:{"content-type":"application/json","x-portal-build":PORTAL_BUILD,"x-blackdomain-portal":"1"},cache:"no-store",body:JSON.stringify({text}),signal:controller.signal});if(response.status===401){authenticated=false;renderLogin();return false;}if(!response.ok)throw new Error(`HTTP ${response.status}`);const data=await response.json();if(revision!==routeRevision)return false;if(!silent&&data.messages?.length)renderResults(data.messages);else if(!silent){showAnalysisState("正在等待即時資料","取得資料後會自動顯示，您可以先切換到遊戲頁面。",{error:false});toast("等待最新資料","取得資料後會自動顯示在目前頁面");}return true;}catch(error){console.error("Portal command failed",error);const recoveringElectronic=revision===routeRevision&&activeOperation?.categoryKey==="atg"&&activeOperation?.mode==="recommend";if(recoveringElectronic&&retryCount<2){await new Promise(resolve=>setTimeout(resolve,1500*(retryCount+1)));if(revision!==routeRevision)return false;return send(text,{showBusy,silent,retryCount:retryCount+1});}if(revision===routeRevision&&!silent){if(recoveringElectronic){showAnalysisState("即時資料連線恢復中","推薦請求會自動補送，連線恢復後顯示結果。",{error:false});toast("正在恢復連線","不需要重新點擊推薦");recoverElectronicRecommendation();}else{showAnalysisState(error.name==="AbortError"?"資料回覆逾時":"資料讀取失敗","請返回上一頁後重新進入，不需要持續等待。",{error:true});toast("資料讀取失敗","目前不會無限停在分析中");}}return false;}finally{clearTimeout(requestTimeout);if(showBusy)loading.hidden=true;}}
document.addEventListener("click",event=>{const sportsGame=event.target.closest("[data-sports-game]");if(sportsGame){event.preventDefault();showSportsGame(Number(sportsGame.dataset.sportsGame));return;}const sportsMove=event.target.closest("[data-sports-move]");if(sportsMove){event.preventDefault();const carousel=sportsMove.closest(".sports-carousel");const current=Number(carousel?.dataset.sportsIndex)||0;showSportsGame(current+(sportsMove.dataset.sportsMove==="next"?1:-1));return;}const trackButton=event.target.closest("[data-mb-track]");if(trackButton){event.preventDefault();renderMbCountPicker(trackButton.dataset.mbTrack);return;}const countButton=event.target.closest("[data-mb-count]");if(countButton){event.preventDefault();renderMbConfirmation(Number(countButton.dataset.mbCount));return;}const startButton=event.target.closest("[data-mb-start]");if(startButton){event.preventDefault();startMbAnalysis();return;}const mbBack=event.target.closest("[data-mb-back]");if(mbBack){event.preventDefault();if(mbBack.dataset.mbBack==="counts"&&mbSelection.track)renderMbCountPicker(mbSelection.track.id);else renderMbTrackPicker();return;}const mbRestart=event.target.closest("[data-mb-restart]");if(mbRestart){event.preventDefault();renderMbTrackPicker();return;}const route=event.target.closest("[data-go]");if(route){event.preventDefault();if(normalizePath(route.dataset.go)==="/portal")stopMonitoringAndGoHome();else navigate(route.dataset.go);return;}const command=event.target.closest("[data-command]");if(command){event.preventDefault();if(command.dataset.command==="重新推薦"&&restartElectronicRecommendation())return;send(command.dataset.command);}});
document.addEventListener("submit",event=>{if(!event.target.matches(".baccarat-input-form"))return;event.preventDefault();const input=event.target.querySelector("input");const value=input.value.trim();if(!/^\d+$/.test(value)||Number(value)<=0){toast("輸入格式錯誤","請輸入大於 0 的正整數");input.focus();return;}setAnalysisFlowStep(2);send(value);input.value="";});
addEventListener("popstate",()=>{if(adminMonitorTimer){clearInterval(adminMonitorTimer);adminMonitorTimer=null;}currentPath=normalizePath(location.pathname);activeOperation=null;routeRevision+=1;renderRoute();});
let baccaratSyncInFlight=false;
async function syncActiveBaccarat(){if(!authenticated||activeOperation?.categoryKey!=="baccarat"||baccaratSyncInFlight)return;baccaratSyncInFlight=true;try{await fetch("/api/web/sync",{method:"POST",headers:{"x-blackdomain-portal":"1"},cache:"no-store"});}catch(error){console.error("Baccarat synchronization failed",error);}finally{baccaratSyncInFlight=false;}}
setInterval(syncActiveBaccarat,15_000);
document.addEventListener("visibilitychange",()=>{if(!document.hidden)syncActiveBaccarat();});
async function refreshRuntimeAccess(){if(!authenticated)return;try{const response=await fetch("/api/web/me",{cache:"no-store"});if(response.status===401){authenticated=false;renderLogin();return;}if(!response.ok)return;applyRuntimeAccess(await response.json(),{rerender:true});}catch(error){console.error("Portal access refresh failed",error);}}
setInterval(refreshRuntimeAccess,5_000);
async function recoverElectronicRecommendation(){if(!authenticated||electronicRecoveryInFlight||activeOperation?.categoryKey!=="atg"||activeOperation?.mode!=="recommend"||!document.querySelector("#analysisStage"))return;if(Date.now()-Number(activeOperation.startedAt||0)<4_000)return;electronicRecoveryInFlight=true;try{const response=await fetch("/api/web/me",{cache:"no-store"});if(response.status===401){authenticated=false;renderLogin();return;}if(!response.ok)return;const value=await response.json();const entries=Array.isArray(value.messages)?value.messages:[];const latest=[...entries].reverse().find(entry=>Number(entry.at)>Number(activeOperation.startedAt||0)&&(entry.messages||[]).some(message=>{const data=message.type==="text"?{texts:[message.text]}:walk(message.contents);const content=[message.altText,...(data.texts||[])].filter(Boolean).join(" ");return /AI推薦房|推薦房號/.test(content)&&messageBelongsToActiveOperation(message);}))?.messages||[];if(latest.length)renderResults(latest,{enforceScope:true,automatic:true});}catch(error){console.error("Electronic recommendation recovery failed",error);}finally{electronicRecoveryInFlight=false;}}
setInterval(recoverElectronicRecommendation,5_000);
const ELECTRONIC_CLIENT_TIMEOUT_MS=95_000;
setInterval(()=>{if(!authenticated||activeOperation?.categoryKey!=="atg"||activeOperation?.mode!=="recommend"||!document.querySelector("#analysisStage"))return;if(Date.now()-Number(activeOperation.startedAt||0)<ELECTRONIC_CLIENT_TIMEOUT_MS)return;activeOperation.mode="recommend-timeout";setAnalysisFlowStep(3);showAnalysisState("本次推薦已停止","目前沒有取得足夠的即時空房與 RTP 資料，請稍後再試。",{error:true});toast("推薦已停止","頁面不會繼續卡在分析中");},1_000);
document.addEventListener("visibilitychange",()=>{if(!document.hidden)recoverElectronicRecommendation();});
if(!matchMedia("(prefers-reduced-motion: reduce)").matches&&matchMedia("(hover: hover)").matches){let pointerFrame=0;let cursorX="50%";let cursorY="38%";addEventListener("pointermove",event=>{cursorX=`${Math.max(0,Math.min(100,event.clientX/innerWidth*100)).toFixed(2)}%`;cursorY=`${Math.max(0,Math.min(100,event.clientY/innerHeight*100)).toFixed(2)}%`;if(pointerFrame)return;pointerFrame=requestAnimationFrame(()=>{document.body.style.setProperty("--cursor-x",cursorX);document.body.style.setProperty("--cursor-y",cursorY);pointerFrame=0;});},{passive:true});}
installButton.addEventListener("click",installPwa);
installClose.addEventListener("click",closeInstallDialog);
installConfirm.addEventListener("click",closeInstallDialog);
installDialog.addEventListener("click",event=>{if(event.target===installDialog)closeInstallDialog();});
addEventListener("beforeinstallprompt",event=>{event.preventDefault();deferredInstallPrompt=event;setInstallVisibility();});
addEventListener("appinstalled",()=>{deferredInstallPrompt=null;setInstallVisibility();toast("黑域AI安裝完成","現在可以從桌面直接開啟");});
addEventListener("online",()=>{if(document.querySelector(".offline-screen"))location.reload();else toast("網路已恢復","即時資料將繼續同步");});
addEventListener("offline",()=>{setConnection("offline","網路中斷");toast("網路連線中斷","不會使用快取資料產生分析");});
setInstallVisibility();
if("serviceWorker" in navigator){addEventListener("load",()=>navigator.serviceWorker.register("/portal/sw.js",{scope:"/portal/",updateViaCache:"none"}).then(registration=>registration.update()).catch(error=>console.error("PWA registration failed",error)));}
fetch("/api/web/me").then(response=>response.json()).then(value=>{authenticated=Boolean(value.authenticated);applyRuntimeAccess(value);resumeBaccaratSession=Boolean(value.activeBaccaratSession);resumeBaccaratPlatform=value.activeBaccaratPlatform||null;restoredMessages=Array.isArray(value.messages)?value.messages:[];currentPath=normalizePath(location.pathname);renderRoute();if(!authenticated)return;const events=new EventSource("/api/web/events");events.addEventListener("ready",()=>{setAccessIndicator();refreshRuntimeAccess();syncActiveBaccarat();});events.addEventListener("message",event=>{try{if(activeOperation)renderResults(JSON.parse(event.data),{enforceScope:true,automatic:true});}catch(error){console.error("Portal event parse failed",error);}});events.onerror=()=>setConnection("connecting","重新連線");}).catch(error=>{console.error("Portal initialization failed",error);authenticated=false;accessAllowed=false;if(!navigator.onLine)renderOffline();else renderLogin();});
